float hachage(vec2 p) {
    p = fract(sin(vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)))) * 43758.5453);
    return p.x;
}

float bruit(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(mix(hachage(i + vec2(0.0, 0.0)), hachage(i + vec2(1.0, 0.0)), u.x),
               mix(hachage(i + vec2(0.0, 1.0)), hachage(i + vec2(1.0, 1.0)), u.x), u.y);
}

float bmf(vec2 p) {
    float v = 0.0;
    float a = 0.5;
    vec2 decalage = vec2(100.0);
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
    for (int i = 0; i < 5; ++i) {
        v += a * bruit(p);
        p = rot * p * 2.0 + decalage;
        a *= 0.5;
    }
    return v;
}

float obtenirHauteurMontagne(float x, float frequence, float amplitude, float vitesse, float hauteurBase) {
    float n = bmf(vec2(x * frequence + iTime * vitesse * 0.05, 0.0));
    return sin(x * frequence + iTime * vitesse) * amplitude + (n - 0.5) * amplitude * 1.5 + hauteurBase;
}

vec3 obtenirSoleil(vec2 uv, vec2 posSoleil) {
    float d = length(uv - posSoleil);

    float disqueSoleil = smoothstep(0.09, 0.085, d);

    float aureole = exp(-d * 4.0) * 0.6;
    float rayons = pow(bmf(vec2(atan(uv.y - posSoleil.y, uv.x - posSoleil.x) * 3.0, iTime * 0.1)), 2.0) * exp(-d * 2.0) * 0.3;

    vec3 couleurSoleil = vec3(1.0, 0.95, 0.85) * disqueSoleil * 3.0;
    vec3 couleurLueur = vec3(1.0, 0.5, 0.1) * (aureole + rayons);

    return couleurSoleil + couleurLueur;
}

vec3 obtenirAtmosphere(vec2 uv, vec2 posSoleil) {
    float distSoleil = length(uv - posSoleil);
    vec3 cielHaut = vec3(0.05, 0.15, 0.4);
    vec3 cielHorizon = vec3(0.4, 0.6, 0.85);
    vec3 lueurSoleil = vec3(1.0, 0.6, 0.3) * exp(-distSoleil * 1.5);

    vec3 ciel = mix(cielHorizon, cielHaut, pow(max(uv.y, 0.0), 0.8));
    return ciel + lueurSoleil;
}

vec3 obtenirNuages(vec2 uv) {
    vec2 uvNuage = uv * vec2(1.5, 3.0) + vec2(iTime * 0.02, 0.0);
    float c = bmf(uvNuage * 3.0);
    c = smoothstep(0.4, 0.8, c);
    return vec3(1.0, 0.95, 0.9) * c * 0.4 * pow(max(uv.y, 0.0), 1.5);
}

void mainImage(out vec4 couleurFrag, in vec2 coordFrag) {
    vec2 uv = coordFrag / iResolution.xy;
    vec2 uvAspect = (coordFrag - 0.5 * iResolution.xy) / iResolution.y;

    vec2 posSoleil = vec2(0.35, 0.25);

    vec3 coul = obtenirAtmosphere(uv, posSoleil);
    coul += obtenirSoleil(uvAspect, posSoleil);
    coul += obtenirNuages(uv);

    vec4 couches[4];
    couches[0] = vec4(3.0, 0.12, 0.05, 0.40);
    couches[1] = vec4(6.0, 0.09, 0.10, 0.30);
    couches[2] = vec4(12.0, 0.06, 0.20, 0.20);
    couches[3] = vec4(25.0, 0.02, 0.40, 0.08);

    vec3 couleursBase[4];
    couleursBase[0] = vec3(0.08, 0.25, 0.20);
    couleursBase[1] = vec3(0.10, 0.38, 0.22);
    couleursBase[2] = vec3(0.12, 0.50, 0.24);
    couleursBase[3] = vec3(0.20, 0.65, 0.28);

    float pasPixelX = 1.0 / iResolution.x;

    for (int i = 0; i < 4; i++) {
        float freq = couches[i].x;
        float amp = couches[i].y;
        float vitesse = couches[i].z;
        float hauteurBase = couches[i].w;

        float h = obtenirHauteurMontagne(uv.x, freq, amp, vitesse, hauteurBase);

        float largeurBord = fwidth(uv.y - h);
        float arondat = smoothstep(h + largeurBord, h - largeurBord, uv.y);

        if (arondat > 0.0) {
            float hDroite = obtenirHauteurMontagne(uv.x + pasPixelX, freq, amp, vitesse, hauteurBase);
            float pente = (hDroite - h) / pasPixelX;

            vec2 normale = normalize(vec2(-pente, 1.0));

            vec2 dirLumiere = normalize(posSoleil - (uv - vec2(0.5)));
            float diff = max(dot(normale, dirLumiere), 0.0);

            vec3 coulCouche = couleursBase[i];
            coulCouche *= (0.5 + 0.6 * diff);

            float facteurBrouillard = exp(-float(3 - i) * 0.4);
            vec3 couleurBrouillard = mix(vec3(0.5, 0.65, 0.85), vec3(1.0, 0.7, 0.4), exp(-length(uvAspect - posSoleil) * 2.0));
            coulCouche = mix(couleurBrouillard, coulCouche, facteurBrouillard);

            float rehaut = pow(1.0 - clamp(abs(uv.y - h) / 0.02, 0.0, 1.0), 3.0) * diff;
            coulCouche += vec3(1.0, 0.8, 0.5) * rehaut * 0.4 * facteurBrouillard;

            coul = mix(coul, coulCouche, arondat);
        }
    }

    coul = vec3(1.0) - exp(-coul * 1.2);
    coul = pow(coul, vec3(1.0 / 2.2));

    vec2 q = uv * (1.0 - uv.yx);
    float vig = q.x * q.y * 15.0;
    coul *= pow(max(vig, 0.0), 0.25);

    couleurFrag = vec4(coul, 1.0);
}
